def diagnose(train_err, val_err, target=0.10):
    gap = val_err - train_err
    if train_err > target and gap < 0.05:
        return "underfitting: add features or capacity"
    if gap >= 0.05:
        return "overfitting: regularise, simplify, or get more data"
    return "good fit for the target"

# Polynomial degree vs errors from cross-validation (illustrative numbers).
curve = {1: (0.30, 0.31), 3: (0.09, 0.10), 9: (0.01, 0.24)}
for degree, (tr, va) in curve.items():
    print(degree, diagnose(tr, va))
# 1 underfitting. 3 good fit. 9 overfitting.

# Regularisation: penalise large weights. Stronger lambda = simpler model.
def ridge_loss(errors, weights, lam):
    return sum(e * e for e in errors) + lam * sum(w * w for w in weights)
print(ridge_loss([1, -1], [3, 4], 0.1), ridge_loss([1, -1], [3, 4], 1.0))   # 4.5 27.0
```

| Pattern | Diagnosis | Try |
|---|---|---|
| both high, small gap. | underfit (bias). | features, capacity, less regularisation. |
| low train, high val. | overfit (variance). | regularise, simplify, more data. |
| both low. | good fit. | check the test set once. |

